/*
 * As categorias da wiki (modelo próprio, com nome, cor, ícone e contagem):
 * a lista do store, o símbolo e o badge do tema, e o `category-chooser` do
 * composer. Usadas pelas telas (./pages) e pelo composer do artigo
 * (./composer).
 */
import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import classList from 'flarum/common/utils/classList';
import SelectKit from '../../composer/SelectKit';
import { categorySymbol } from '../../utils/tags';
import { t } from '../../utils/settings';
import { wikiIndexUrl, wt } from './shared';

// ---------------------------------------------------------------------
// Categorias da wiki (modelo próprio, com nome, cor, ícone e contagem)
// ---------------------------------------------------------------------

export function wikiCategories() {
  return app.store.all('linkrobins-wiki-categories').slice().sort((a, b) => {
    const pa = Number(a.position()) || 0;
    const pb = Number(b.position()) || 0;
    return pa !== pb ? pa - pb : Number(a.id()) - Number(b.id());
  });
}
let categoriesRequested = false;

/**
 * Com a wiki em largura total, a coluna lateral dela (que carrega as
 * categorias) nem é montada: o dropdown pede a lista uma vez.
 */
export function ensureCategories() {
  if (categoriesRequested || app.store.all('linkrobins-wiki-categories').length) return;
  categoriesRequested = true;
  app.store.find('linkrobins-wiki-categories', {
    sort: 'position',
    page: {
      limit: 100
    }
  }).then(() => m.redraw()).catch(() => {});
}

/** O símbolo do tema (quadradinho na cor, ou o ícone) para uma categoria da wiki. */
export function symbolOf(category) {
  return categorySymbol(category);
}
export function categoryUrl(key) {
  return wikiIndexUrl({
    category: key
  });
}

/** "▪ Guias" — o badge de categoria da lista, levando ao filtro da wiki. */
export function categoryBadge(category) {
  return m(Link, {
    className: "CanelaCategoryBadge",
    href: categoryUrl(String(category.id())),
    title: category.description() || undefined
  }, symbolOf(category), m("span", {
    className: "CanelaCategoryBadge-name"
  }, category.name()));
}

/**
 * O `category-chooser` do composer: "Categoria…" ou o badge da escolhida,
 * com "(sem categoria)" no topo da lista. `value` é o id (ou '').
 */
export function categoryChooser(value, onchange, className, disabled = false) {
  const categories = wikiCategories();
  const chosen = value ? categories.find(category => String(category.id()) === String(value)) : null;
  if (!categories.length) return null;
  const rows = filter => {
    const needle = filter.trim().toLowerCase();
    const list = needle ? [] : [{
      key: '',
      selected: !chosen,
      content: m("div", {
        className: "CanelaCategoryRow CanelaCategoryRow--none"
      }, wt('compose.no_category', 'No category'))
    }];
    categories.filter(category => !needle || String(category.name()).toLowerCase().includes(needle)).forEach(category => list.push({
      key: String(category.id()),
      selected: chosen === category,
      title: category.name(),
      content: m("div", {
        className: "CanelaCategoryRow"
      }, m("div", {
        className: "CanelaCategoryRow-status"
      }, m("span", {
        className: "CanelaChooserBadge"
      }, symbolOf(category), m("span", {
        className: "CanelaChooserBadge-name"
      }, category.name())), m("span", {
        className: "CanelaCategoryRow-count"
      }, "\xD7 ", Number(category.articleCount?.() || 0))), category.description() ? m("div", {
        className: "CanelaCategoryRow-desc"
      }, category.description()) : null)
    }));
    return list;
  };
  return m(SelectKit, {
    className: classList(className, {
      'has-selection': !!chosen
    }),
    label: t('thirdparty.wiki.category_placeholder'),
    disabled: disabled,
    filterIcon: true,
    header: chosen ? m("span", {
      className: "CanelaComposerFields-value"
    }, m("span", {
      className: "CanelaChooserBadge"
    }, symbolOf(chosen), m("span", {
      className: "CanelaChooserBadge-name"
    }, chosen.name()))) : m("span", {
      className: "CanelaComposerFields-placeholder"
    }, t('thirdparty.wiki.category_placeholder')),
    rows: rows,
    onselect: key => onchange(key)
  });
}
flarum.reg.add('ramon-canela', 'forum/thirdparty/wiki/categories', { wikiCategories: wikiCategories,ensureCategories: ensureCategories,symbolOf: symbolOf,categoryUrl: categoryUrl,categoryBadge: categoryBadge,categoryChooser: categoryChooser, });