/** A categoria filtrada no índice (pelo id ou pelo slug), se houver. */
function indexCategory(page) {
  const current = page.category ? String(page.category) : '';
  if (!current || current === NO_CATEGORY) return null;
  return wikiCategories().find(category => String(category.id()) === current || category.slug?.() === current) || null;
}

/** O hero do índice: "Wiki", o nome da categoria (com a descrição) ou a busca. */
function indexHero(page) {
  const query = String(page.query || '').trim();

  // O layout próprio do admin traz os títulos dele.
  if (!query && !page.category && page.blocks?.length) return null;
  const category = query ? null : indexCategory(page);
  const uncategorised = !query && page.category === NO_CATEGORY;
  let title = wt('nav', 'Wiki');
  if (query) title = wt('search.results_heading', `Results for "${query}"`, {
    query
  });else if (category) title = category.name();else if (uncategorised) title = wt('index.uncategorised', 'Other');
  const home = !query && !category && !uncategorised;
  const description = category ? category.description() || null : home ? wtr('hero_description') : null;

  // Os números da wiki (a soma das categorias): "12 artigos · 3 categorias";
  // numa categoria, só os artigos dela.
  const categories = wikiCategories();
  const articles = category ? Number(category.articleCount?.() || 0) : categories.reduce((sum, item) => sum + (Number(item.articleCount?.() || 0) || 0), 0);
  const stats = [];
  if (!query && articles > 0) stats.push(wtr('hero_articles', {
    count: articles
  }));
  if (home && categories.length > 0) stats.push(wtr('hero_categories', {
    count: categories.length
  }));
  return m("header", {
    className: classList('Hero CanelaCategoryHero CanelaWikiHero', {
      'CanelaWikiHero--home': home
    }),
    style: category?.color() ? {
      '--category-color': category.color()
    } : undefined
  }, m("div", {
    className: "container"
  }, m("h1", {
    className: "CanelaCategoryHero-title"
  }, category ? m("span", {
    className: "CanelaCategoryHero-icon"
  }, symbolOf(category)) : null, title), description ? m("p", {
    className: "CanelaCategoryHero-description"
  }, description) : null, stats.length ? m("p", {
    className: "CanelaWikiHero-stats"
  }, stats.join(' · ')) : null));
}

