function copyLink(article) {
  const url = window.location.origin + wikiArticleUrl(article);
  const nav = navigator;
  if (typeof nav.share === 'function' && window.matchMedia?.('(pointer: coarse)').matches) {
    nav.share({
      title: article.title(),
      url
    }).catch(() => {});
    return;
  }
  const done = () => app.alerts.show({
    type: 'success'
  }, t('topic.link_copied'));
  if (navigator.clipboard?.writeText) navigator.clipboard.writeText(url).then(done, () => window.prompt('', url));else window.prompt('', url);
}

